mapper.select:
select *
from (
         (select CONTENTVALUE as col1, ROWNUMBER as col2, COLNUMBER as col3 from PROFITSHEETTEXTBASIC)
         union
         (
             select FORMAT(ItemValue, 2), RowNumber, ColNumber
             from PROFITSHEETONEITEMBASIC,
                  PROFITSHEET
             where PROFITSHEETONEITEMBASIC.OneItem = PROFITSHEET.OneItem
               and USERUNIQUE = #{userUnique}
               and PERIOD = #{period}
         )
         union
         (select FORMAT(t3.IV, 2), CalRow, CalCol
          from PROFITSHEETCALBASIC,
               (select PROFITSHEETCALBASIC.CalCellID                                   as calid,
                       Sum(PROFITSHEET.ItemValue * PROFITSHEETCALRELATIONBASIC.Signal) as
                                                                                          IV
                from PROFITSHEET,
                     PROFITSHEETCALRELATIONBASIC,
                     PROFITSHEETCALBASIC
                where PROFITSHEET.OneItem = PROFITSHEETCALRELATIONBASIC.OneItem
                  and PROFITSHEETCALBASIC.CALCELLID = PROFITSHEETCALRELATIONBASIC.CALCELLID
                  and USERUNIQUE = #{userUnique}
                  and PERIOD = #{period}
                group by PROFITSHEETCALBASIC.CALCELLID
               ) t3
          where PROFITSHEETCALBASIC.CalCellID = t3.calid
         )
     ) tt
order by col2, col3;
